{
  "private": true,
  "type": "module",
  "scripts": {
    "build": "echo \"no build step configured\""
  },
  "devDependencies": {
    "vitest": "^3.1.3"
  }
}

import { createServer } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFile, rename, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(fileURLToPath(import.meta.url));
const publicDir = path.join(root, 'public');
const dataDir = path.join(root, 'data');
const booksFile = path.join(dataDir, 'books.json');
const port = Number(process.env.PORT || 3000);

await mkdir(dataDir, { recursive: true });
try {
  await readFile(booksFile, 'utf8');
} catch (error) {
  if (error.code !== 'ENOENT') throw error;
  await writeFile(booksFile, '[]\n', 'utf8');
}

async function readBooks() {
  const contents = await readFile(booksFile, 'utf8');
  const books = JSON.parse(contents);
  if (!Array.isArray(books)) throw new Error('The books file must contain a JSON array.');
  return books;
}

async function writeBooks(books) {
  const temporaryFile = `${booksFile}.${randomUUID()}.tmp`;
  await writeFile(temporaryFile, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
  await rename(temporaryFile, booksFile);
}

let writeQueue = Promise.resolve();
function updateBooks(update) {
  const operation = writeQueue.then(async () => {
    const books = await readBooks();
    const result = update(books);
    if (result?.save !== false) await writeBooks(books);
    return result?.value;
  });
  writeQueue = operation.catch(() => {});
  return operation;
}

function json(response, status, value) {
  response.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
  });
  response.end(JSON.stringify(value));
}

async function readBody(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (body.length > 1_000_000) throw new Error('Request body is too large.');
  }
  try {
    return JSON.parse(body || '{}');
  } catch {
    throw new Error('Please send valid JSON.');
  }
}

function cleanText(value, limit) {
  return typeof value === 'string' ? value.trim().slice(0, limit) : '';
}

async function handleApi(request, response, url) {
  if (url.pathname === '/api/books' && request.method === 'GET') {
    return json(response, 200, await readBooks());
  }

  if (url.pathname === '/api/books' && request.method === 'POST') {
    let input;
    try {
      input = await readBody(request);
    } catch (error) {
      return json(response, 400, { error: error.message });
    }
    if (!input || typeof input !== 'object' || Array.isArray(input)) {
      return json(response, 400, { error: 'Book details must be sent as an object.' });
    }

    const title = cleanText(input.title, 180);
    const author = cleanText(input.author, 120);
    const notes = cleanText(input.notes, 5000);
    if (!title || !author) {
      return json(response, 400, { error: 'Add a title and author to save this book.' });
    }

    const book = {
      id: randomUUID(),
      title,
      author,
      notes,
      status: 'reading',
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    await updateBooks((books) => books.unshift(book));
    return json(response, 201, book);
  }

  const match = url.pathname.match(/^\/api\/books\/([^/]+)$/);
  if (match) {
    let id;
    try {
      id = decodeURIComponent(match[1]);
    } catch {
      return json(response, 400, { error: 'Invalid book id.' });
    }

    if (request.method === 'GET') {
      const book = (await readBooks()).find((item) => item.id === id);
      return book
        ? json(response, 200, book)
        : json(response, 404, { error: 'Book not found.' });
    }

    if (request.method === 'PATCH') {
      let input;
      try {
        input = await readBody(request);
      } catch (error) {
        return json(response, 400, { error: error.message });
      }
      if (!input || typeof input !== 'object' || Array.isArray(input)) {
        return json(response, 400, { error: 'Book details must be sent as an object.' });
      }
      if (typeof input.finished !== 'boolean') {
        return json(response, 400, { error: 'Choose whether this book is finished.' });
      }
      const result = await updateBooks((books) => {
        const book = books.find((item) => item.id === id);
        if (!book) return { save: false, value: null };
        book.status = input.finished ? 'finished' : 'reading';
        book.finishedAt = input.finished ? new Date().toISOString() : null;
        return { value: book };
      });
      return result
        ? json(response, 200, result)
        : json(response, 404, { error: 'Book not found.' });
    }
  }

  json(response, 404, { error: 'Not found.' });
}

const contentTypes = {
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.svg': 'image/svg+xml',
};

async function servePage(response, pathname) {
  const assetNames = new Set(['/app.css', '/app.js', '/mark.svg']);
  if (assetNames.has(pathname)) {
    const assetPath = path.join(publicDir, pathname.slice(1));
    try {
      const content = await readFile(assetPath);
      response.writeHead(200, {
        'Content-Type': contentTypes[path.extname(assetPath)] || 'application/octet-stream',
        'Cache-Control': 'no-cache',
      });
      response.end(content);
    } catch {
      response.writeHead(404);
      response.end('Not found');
    }
    return;
  }

  try {
    const html = await readFile(path.join(publicDir, 'index.html'));
    response.writeHead(200, {
      'Content-Type': 'text/html; charset=utf-8',
      'Cache-Control': 'no-cache',
    });
    response.end(html);
  } catch {
    response.writeHead(500);
    response.end('The app could not be loaded.');
  }
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, `http://${request.headers.host || 'localhost'}`);
  try {
    if (url.pathname.startsWith('/api/')) {
      await handleApi(request, response, url);
    } else {
      await servePage(response, url.pathname);
    }
  } catch (error) {
    console.error(error);
    if (!response.headersSent) json(response, 500, { error: 'Something went wrong. Please try again.' });
    else response.end();
  }
});

server.listen(port, '0.0.0.0', () => {
  console.log(`Reading journal listening on http://localhost:${port}`);
});
